CREATE TABLE discovered_jobs (id UUID PRIMARY KEY,external_id VARCHAR(255) NOT NULL,connector_id VARCHAR(255) NOT NULL,source VARCHAR(255) NOT NULL,source_url VARCHAR(2000),title VARCHAR(500) NOT NULL,company VARCHAR(500) NOT NULL,location VARCHAR(500),employment_type VARCHAR(50),work_mode VARCHAR(50),salary VARCHAR(255),posted_date TIMESTAMP,raw_content TEXT NOT NULL,metadata_json TEXT,content_hash VARCHAR(64) NOT NULL,normalized_title VARCHAR(500),normalized_company VARCHAR(500),sync_state VARCHAR(32) NOT NULL,discovered_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,last_seen_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_discovered_connector_external UNIQUE(connector_id,external_id));
CREATE INDEX idx_discovered_job_hash ON discovered_jobs(content_hash); CREATE INDEX idx_discovered_job_sync ON discovered_jobs(connector_id,sync_state);
